/// A run request whose trigger names the account's own name as the person (a `by` the UI claims is dropped).
fn started_by(mut req: StartRequest, who: &str) -> StartRequest {
    req.trigger.by = who.into();
    req
}

/// The card decision with the person replaced by the account's own name.
fn by_who(d: CardDecision, who: &str) -> CardDecision {
    match d {
        CardDecision::Approve { .. } => CardDecision::Approve { by: who.into() },
        CardDecision::Reject { note, .. } => CardDecision::Reject { by: who.into(), note },
        CardDecision::Edit { patch, .. } => CardDecision::Edit { by: who.into(), patch },
        CardDecision::Investigate { .. } => CardDecision::Investigate { by: who.into() },
    }
}
